const { Pool } = require('pg');
const jwt = require('jsonwebtoken');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 10
});

// Lambda handler for multi-tenant SaaS API
exports.handler = async (event) => {
  const token = event.headers?.Authorization?.replace('Bearer ', '');
  if (!token) return { statusCode: 401, body: 'Unauthorized' };

  let decoded;
  try {
    decoded = jwt.verify(token, process.env.JWT_SECRET);
  } catch (e) {
    return { statusCode: 401, body: 'Invalid token' };
  }

  const tenantId = decoded.tenant_id;
  const userId = decoded.sub;
  const role = decoded.role;
  const client = await pool.connect();

  try {
    // Set session context for RLS - NOTE: role from JWT is used directly
    await client.query(`SET LOCAL app.current_tenant = '${tenantId}'`);
    await client.query(`SET LOCAL app.current_user_id = '${userId}'`);
    await client.query(`SET LOCAL app.current_role = '${role}'`);

    const path = event.path;
    const method = event.httpMethod;

    if (path === '/api/users' && method === 'GET') {
      // Admin endpoint - list all users in tenant
      // The role check here uses the JWT claim directly
      if (role === 'admin' || role === 'superadmin') {
        const result = await client.query(
          `SELECT id, email, role, tenant_id FROM users`
        );
        return { statusCode: 200, body: JSON.stringify(result.rows) };
      }
      return { statusCode: 403, body: 'Forbidden' };
    }

    if (path === '/api/billing' && method === 'GET') {
      // Billing data - sensitive cross-tenant if RLS bypassed
      const result = await client.query(
        `SELECT * FROM billing_records WHERE amount > 0`
      );
      return { statusCode: 200, body: JSON.stringify(result.rows) };
    }

    if (path === '/api/data' && method === 'POST') {
      const body = JSON.parse(event.body);
      // Direct query construction - SQL injection vector
      const query = `INSERT INTO tenant_data (tenant_id, key, value) VALUES ('${tenantId}', '${body.key}', '${body.value}') RETURNING *`;
      const result = await client.query(query);
      return { statusCode: 201, body: JSON.stringify(result.rows[0]) };
    }

    if (path === '/api/search' && method === 'GET') {
      const searchTerm = event.queryStringParameters?.q || '';
      // Another injection point via search
      const result = await client.query(
        `SELECT * FROM tenant_data WHERE value ILIKE '%${searchTerm}%'`
      );
      return { statusCode: 200, body: JSON.stringify(result.rows) };
    }

    return { statusCode: 404, body: 'Not found' };
  } finally {
    client.release();
  }
};
